<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, reactive, ref, watch } from 'vue'
import { api, post, query, requestId, datetime, contextVersion, contextChanged, isCancelled } from '../lib/api'
import { selectedDate, isParent } from '../lib/state'
import { openDialog, closeDialog, notify, useResource, loadStudents, studentOptions, type DialogConfig, type FormValues } from '../lib/ui'
import { authorizationPayload, pickupPeriod, pickupShareText, sharePickupText, type AuthorizationDraft, type Leave, type Pickup, type PickupAlert, type PickupContact } from '../lib/pickup'
import PageHeader from '../components/PageHeader.vue'
import SoftSelect from '../components/SoftSelect.vue'
import StatusBadge from '../components/StatusBadge.vue'
import LoadState from '../components/LoadState.vue'
import AppIcon from '../components/AppIcon.vue'

const tab=ref('pickups'),studentId=ref<string|number>(''),authorizationTab=ref('active')
const issued=ref<Pickup|null>(null),shareError=ref(''),busy=ref(false),actionError=ref(''),avatarFailed=ref<Record<number,boolean>>({})
const wizardOpen=ref(false),step=ref(1),wizardElement=ref<HTMLElement>(),confirmed=ref(false)
const contactSnapshot=ref<PickupContact|null>(null)
const draft=reactive<AuthorizationDraft>({studentId:'',contactId:'',pickupName:'',relationship:'亲属',phone:'',mode:'SINGLE',startDate:selectedDate.value,endDate:selectedDate.value,startTime:'18:30',endTime:'20:00',note:'',requestId:''})
let generation=0,disposed=false,ownDialog=false,previousFocus:HTMLElement|null=null
const current=(started:number)=>!disposed&&started===generation
const students=useResource(loadStudents)
const options=computed(()=>studentOptions(students.data.value||[]))
const child=computed(()=>students.data.value?.find(row=>row.id===Number(studentId.value)))
const draftChild=computed(()=>students.data.value?.find(row=>row.id===Number(draft.studentId)))
const contacts=useResource(()=>studentId.value?api<PickupContact[]>('/pickup-contacts'+query({studentId:studentId.value})):Promise.resolve([]),[studentId])
const {data,loading,error,refresh}=useResource(async()=>{
  const [pickups,leaves]=await Promise.all([api<Pickup[]>('/pickups'+query({studentId:studentId.value})),api<Leave[]>('/leaves'+query({date:selectedDate.value,studentId:studentId.value}))])
  return {pickups,leaves}
},[selectedDate,studentId])
const alerts=useResource(()=>api<PickupAlert[]>('/pickup-alerts'+query({date:selectedDate.value,studentId:studentId.value})),[selectedDate,studentId])
const activePickups=computed(()=>(data.value?.pickups||[]).filter(row=>row.effectiveStatus==='ACTIVE'))
const historicalPickups=computed(()=>(data.value?.pickups||[]).filter(row=>row.effectiveStatus!=='ACTIVE'))
const shownPickups=computed(()=>authorizationTab.value==='active'?activePickups.value:historicalPickups.value)
const openAlerts=computed(()=>(alerts.data.value||[]).filter(row=>row.status!=='RESOLVED'))
const contactOptions=computed(()=>[{value:'',label:'临时接送人 · 手动填写'},...(contacts.data.value||[]).map(row=>({value:String(row.id),label:`${row.name} · ${row.relationship}${row.isDefault?'（默认）':''}`}))])
const selectedContact=computed(()=>contactSnapshot.value?.id===Number(draft.contactId)?contactSnapshot.value:null)
const relationships=['妈妈','爸爸','奶奶','爷爷','外婆','外公','亲属','朋友','其他'].map(label=>({value:label,label}))
const hasAlert=(sid:number)=>openAlerts.value.some(row=>row.studentId===sid)
function closeWizard() { if(busy.value) return; wizardOpen.value=false }
function resetLocal() {
  generation++; busy.value=false; issued.value=null; shareError.value=''; actionError.value=''; avatarFailed.value={}; wizardOpen.value=false; confirmed.value=false
  contactSnapshot.value=null
  Object.assign(draft,{studentId:'',contactId:'',expectedContactVersion:undefined,pickupName:'',relationship:'亲属',phone:'',note:'',requestId:''})
  if(ownDialog) {ownDialog=false;closeDialog()}
}
watch([contextVersion,selectedDate,studentId],resetLocal,{flush:'sync'})
watch(contextVersion,()=>{studentId.value='';authorizationTab.value='active'},{flush:'sync'})
watch(students.data,rows=>{if(isParent.value&&rows?.length&&!rows.some(row=>row.id===Number(studentId.value))) studentId.value=rows[0]!.id})
watch(data,rows=>{if(issued.value&&rows?.pickups.some(row=>row.id===issued.value?.id&&row.effectiveStatus!=='ACTIVE'))issued.value=null})
watch(()=>[draft.pickupName,draft.phone,draft.contactId],()=>{confirmed.value=false})
function snapshotContact() {
  const row=contacts.data.value?.find(row=>row.id===Number(draft.contactId))
  contactSnapshot.value=row?{...row}:null;draft.expectedContactVersion=row?.version
}
watch(()=>draft.contactId,snapshotContact,{flush:'sync'})
watch(wizardOpen,async open=>{
  if(open) {previousFocus=document.activeElement as HTMLElement;document.body.style.overflow='hidden';await nextTick();wizardElement.value?.querySelector<HTMLElement>('button,input')?.focus()}
  else {document.body.style.overflow='';previousFocus?.focus()}
})
onBeforeUnmount(()=>{disposed=true;generation++;if(ownDialog)closeDialog();if(wizardOpen.value)document.body.style.overflow=''})
function wizardKey(event:KeyboardEvent) {
  if(event.key==='Escape') {event.preventDefault();closeWizard()}
  if(event.key!=='Tab') return
  const nodes=wizardElement.value?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),textarea:not(:disabled),a[href]')
  if(!nodes?.length) return
  const first=nodes[0]!,last=nodes[nodes.length-1]!
  if(event.shiftKey&&document.activeElement===first) {event.preventDefault();last.focus()}
  else if(!event.shiftKey&&document.activeElement===last) {event.preventDefault();first.focus()}
}
async function refreshAll() {await Promise.all([refresh(),contacts.refresh(),alerts.refresh()])}
async function dialogAction<T>(config:Omit<DialogConfig,'submit'>&{submit:(values:FormValues)=>Promise<T>},saved?:(result:T)=>void) {
  const started=generation;let result:T;ownDialog=true
  try {
    const accepted=await openDialog({...config,submit:async values=>{if(!current(started))throw contextChanged();result=await config.submit(values);if(!current(started))throw contextChanged();return result}})
    if(accepted&&current(started)) {saved?.(result!);await refreshAll()}
  } finally {if(current(started))ownDialog=false}
}
async function leave() {
  const key=requestId()
  await dialogAction({title:'申请整日请假',description:'请假经另一位校长或老板批准后，当天不签到、不扣课；临时返校请先撤销已批准请假。',fields:[{key:'studentId',label:'学生',type:'select',options:options.value,required:true},{key:'date',label:'请假日期',type:'date',required:true},{key:'reason',label:'请假原因',type:'textarea',required:true}],initial:{studentId:studentId.value||'',date:selectedDate.value},submit:v=>post('/leaves',{...v,requestId:key}),success:'请假已提交，等待校长审核'})
}
async function review(row:Leave) {
  await dialogAction({title:`审核请假 · ${row.studentName}`,description:`${row.leaveDate} · ${row.reason}`,fields:[{key:'approved',label:'审核结果',type:'select',options:[{value:'yes',label:'批准整日请假'},{value:'no',label:'驳回申请'}],required:true},{key:'note',label:'审核意见',type:'textarea',required:true}],initial:{approved:'yes'},submit:v=>post(`/leaves/${row.id}/review`,{approved:v.approved==='yes',note:v.note,expectedVersion:row.version}),success:'审核结果已记录'})
}
async function cancel(row:Leave) {
  await dialogAction({title:`撤销请假 · ${row.studentName}`,description:'撤销后恢复正常签到和排课结算规则，仍须现场核验后离校。',fields:[{key:'note',label:'撤销原因',type:'textarea',required:true}],submit:v=>post(`/leaves/${row.id}/cancel`,{...v,expectedVersion:row.version}),success:'请假已撤销'})
}
async function editContact(row?:PickupContact) {
  if(!isParent.value||!studentId.value||row&&!row.canManage) return
  const sid=Number(studentId.value),key=requestId()
  await dialogAction({title:row?'编辑常用接送人':'添加常用接送人',description:`${child.value?.name} · 由当前绑定监护人维护。修改联系人会使关联的有效授权失效，请重新安排接送。`,fields:[{key:'name',label:'接送人姓名',required:true},{key:'relationship',label:'与孩子关系',type:'select',options:relationships,required:true},{key:'phone',label:'手机号',required:true},{key:'defaults',label:'接送偏好',type:'multi',options:[{value:'yes',label:'设为默认接送人'}]}],initial:{name:row?.name||'',relationship:row?.relationship||'亲属',phone:row?.phone||'',defaults:row?.isDefault?['yes']:[]},submit:v=>api('/pickup-contacts'+(row?`/${row.id}`:''),{method:row?'PATCH':'POST',body:{studentId:sid,name:v.name,relationship:v.relationship,phone:v.phone,isDefault:v.defaults.includes('yes'),...(row?{expectedVersion:row.version}:{requestId:key})}}),success:row?'常用接送人已更新':'常用接送人已添加'})
}
async function contactDefault(row:PickupContact) {
  await dialogAction({title:`将${row.name}设为默认接送人`,description:'默认联系人仅用于快速选择。接送仍须另行登记有效授权，并由老师现场核对。',confirm:'设为默认',submit:()=>post(`/pickup-contacts/${row.id}/default`,{expectedVersion:row.version}),success:'默认接送人已更新'})
}
async function removeContact(row:PickupContact) {
  await dialogAction({title:`移除常用接送人 · ${row.name}`,danger:true,description:'移除后相关有效授权一并撤销。历史交接记录保留，老师不能继续凭旧授权放行。',confirm:'确认移除',submit:()=>api(`/pickup-contacts/${row.id}`,{method:'DELETE',body:{expectedVersion:row.version}}),success:'常用接送人已移除'})
}
function authorize(contact?:PickupContact) {
  if(!isParent.value) return
  const sid=Number(studentId.value)||students.data.value?.[0]?.id
  if(!sid) {notify('请先绑定需要接送的孩子','error');return}
  if(!studentId.value)studentId.value=sid
  const defaultContact=contact||(contacts.data.value||[]).find(row=>row.isDefault)
  Object.assign(draft,{studentId:sid,contactId:defaultContact?String(defaultContact.id):'',pickupName:'',relationship:'亲属',phone:'',mode:'SINGLE',startDate:selectedDate.value,endDate:selectedDate.value,startTime:'18:30',endTime:'20:00',note:'',requestId:requestId()})
  snapshotContact()
  step.value=1;confirmed.value=false;actionError.value='';wizardOpen.value=true
}
function nextStep() {
  actionError.value=''
  try {
    if(draft.mode==='SINGLE')draft.endDate=draft.startDate
    authorizationPayload(draft)
    step.value=2
  } catch(error) {actionError.value=(error as Error).message}
}
async function submitAuthorization() {
  if(busy.value||!confirmed.value)return
  const started=generation;busy.value=true;actionError.value=''
  try {
    const result=await post<Pickup>('/pickups',authorizationPayload(draft))
    if(!current(started))return
    wizardOpen.value=false;issued.value=result;shareError.value='';authorizationTab.value='active';notify('接送授权已登记，请将接送信息交给接送人')
    await refreshAll()
  } catch(error) {if(current(started)&&!isCancelled(error))actionError.value=(error as Error).message}
  finally {if(current(started))busy.value=false}
}
async function revoke(row:Pickup,rotate=false) {
  await dialogAction({title:rotate?'重置接送码':`确认撤销${row.pickupName}的接送授权？`,danger:!rotate,description:rotate?'旧接送码和旧核验立即失效，新接送码仅本次显示。':`${row.studentName} · ${pickupPeriod(row)}\n撤销后该接送人不能再凭此授权接走孩子。站内记录立即更新，请自行告知接送人。`,confirm:rotate?'重置接送码':'确认撤销',fields:rotate?[]:[{key:'note',label:'撤销原因',type:'textarea',required:true}],submit:v=>post<Pickup>(`/pickups/${row.id}/${rotate?'rotate-code':'revoke'}`,{...v,expectedVersion:row.version}),success:rotate?'接送码已重置':'已撤销接送授权'},result=>{issued.value=rotate?result:null;shareError.value=''})
}
async function verify(row:Pickup) {
  const key=requestId(),started=generation
  await dialogAction({title:`现场核验 · ${row.studentName}`,description:'请由接送人主动提供信息。人脸服务未配置时，使用接送码与现场核对。核验通过后10分钟内，由本次核验老师确认实际离校。',fields:[{key:'pickupName',label:'现场确认的接送人姓名',required:true},{key:'phoneLast4',label:'电话后四位',required:true},{key:'code',label:'六位接送码',required:true},{key:'identity',label:'现场核对确认',type:'multi',options:[{value:'checked',label:'已当面核对接送人及授权信息'}],required:true}],submit:async v=>{try{return await post(`/pickups/${row.id}/verify`,{pickupName:v.pickupName,phoneLast4:v.phoneLast4,code:v.code,confirmedIdentity:v.identity.includes('checked'),expectedVersion:row.version,requestId:key})}catch(error){if(current(started))await alerts.refresh();throw error}},success:'接送码与现场信息核验通过，请继续确认实际交接'})
}
async function checkout(row:Pickup) {
  if(hasAlert(row.studentId)) {notify('该孩子仍有未解除的异常，请先联系家长并处理','error');return}
  const date=selectedDate.value
  await dialogAction({title:`确认实际离校 · ${row.studentName}`,description:`接送人 ${row.pickupName}（${row.relationship}）。确认后记录离校并按当日排课结算课时，本次授权使用同时留痕。`,confirm:'已实际交接，确认离校',submit:async()=>{const result=await post<{results:{success:boolean;message:string}[]}>('/attendance/check-out',{studentIds:[row.studentId],date});if(!result.results[0]?.success)throw new Error(result.results[0]?.message||'离校未成功');return result},success:'孩子离校与接送使用记录已保存'})
}
async function reportAlert() {
  const key=requestId()
  await dialogAction({title:'登记异常接送提醒',description:'出现未授权接送人、信息不符或其他异常时，先联系监护人确认。异常解除前暂停离校。',fields:[{key:'studentId',label:'孩子',type:'select',options:options.value,required:true},{key:'pickupName',label:'现场接送人姓名',required:true},{key:'phoneLast4',label:'现场提供的电话后四位',required:true},{key:'reason',label:'异常情况',type:'textarea',required:true}],initial:{studentId:studentId.value||''},submit:v=>post('/pickup-alerts',{...v,requestId:key}),success:'异常已登记，暂缓离校'})
}
async function handleAlert(row:PickupAlert,action:'HOLD'|'RESOLVED') {
  await dialogAction({title:action==='HOLD'?'确认暂不离校':'记录异常处理结果',description:action==='HOLD'?`${row.studentName}将保持暂停离校，请填写联系家长及现场安置情况。`:'解除异常只恢复正常接送流程，不能替代有效授权、接送码核验和实际交接确认。',fields:[{key:'note',label:action==='HOLD'?'暂缓原因与已采取措施':'监护人沟通及处理说明',type:'textarea',required:true}],confirm:action==='HOLD'?'登记暂不离校':'解除本条异常',submit:v=>post(`/pickup-alerts/${row.id}/handle`,{action,note:v.note,expectedVersion:row.version}),success:action==='HOLD'?'已登记暂不离校，异常继续拦截':'异常处理结果已保存'})
}
async function shareCode(native=false) {
  const row=issued.value,started=generation
  if(!row)return
  shareError.value=''
  try {
    const text=pickupShareText(row,row.pickupCode||'')
    const result=await sharePickupText(text,native,{share:navigator.share?.bind(navigator),copy:navigator.clipboard?.writeText.bind(navigator.clipboard)})
    if(current(started)&&result==='copied')notify('接送信息已复制，请仅发给本次接送人')
  } catch(error) {if(current(started)&&!isCancelled(error))shareError.value=(error as Error).message}
}
const shareText=computed(()=>{try{return issued.value?pickupShareText(issued.value,issued.value.pickupCode||''):''}catch{return ''}})
</script>

<template>
  <PageHeader title="请假与安全接送" subtitle="把每一次接送安排清楚，把孩子安心交到可信的人手中。"><button class="btn secondary" @click="leave">申请整日请假</button><button v-if="isParent" class="btn primary" @click="authorize()"><AppIcon name="Plus" :size="17" />申请临时接送授权</button><button v-else class="btn secondary" @click="reportAlert"><AppIcon name="TriangleAlert" :size="16" />登记接送异常</button></PageHeader>
  <section v-if="issued" class="issued-card panel" role="status" aria-live="polite"><div class="issued-check"><AppIcon name="CircleCheck" :size="32" /></div><div class="issued-copy"><span class="eyebrow">接送安排已登记</span><h2>{{issued.pickupName}} · {{issued.relationship}}</h2><p>{{issued.studentName}} · {{pickupPeriod(issued)}}</p><p class="muted">请自行告知接送人，校区可在站内查看授权；不代表已完成核验或离校。</p></div><div class="issued-code"><span>本次接送码</span><strong>{{issued.pickupCode||'未返回新码'}}</strong><small>仅本次展示，请妥善保管</small></div><div class="issued-actions"><button class="btn primary" :disabled="!issued.pickupCode" @click="shareCode(true)">分享接送码</button><button class="btn secondary" :disabled="!issued.pickupCode" @click="shareCode()">复制接送信息</button><button class="text-btn" @click="issued=null">已保存，返回接送管理</button></div><p v-if="shareError" class="inline-error full">{{shareError}}</p><details v-if="shareText" class="share-fallback"><summary>查看可复制的接送信息</summary><pre>{{shareText}}</pre></details></section>
  <section class="panel safety-shell"><div class="filter-bar"><div class="tabs"><button :class="{active:tab==='pickups'}" @click="tab='pickups'">接送管理</button><button :class="{active:tab==='leaves'}" @click="tab='leaves'">整日请假</button></div><SoftSelect v-model="studentId" aria-label="选择请假接送学生" :options="[{value:'',label:'全部授权学生'},...options]" /><span class="muted">{{selectedDate}}</span><button class="text-btn" @click="refreshAll">刷新</button></div>
    <div v-if="tab==='pickups'" class="pickup-content">
      <div class="pickup-intro"><div class="pickup-shield"><AppIcon name="ShieldCheck" :size="32" /></div><div><h2>守护孩子的安全接送</h2><p>监护人安排接送人，老师现场核对，确认实际交接后再离校。</p></div><div class="pickup-intro-count"><strong>{{activePickups.length}}</strong><span>当前有效授权</span></div></div>
      <section v-if="alerts.error.value" class="inline-error" role="alert">{{alerts.error.value}}<button class="text-btn" @click="alerts.refresh">重新读取异常提醒</button></section>
      <section v-if="openAlerts.length" class="alert-section" aria-label="异常接送提醒"><div class="section-heading"><h2><AppIcon name="TriangleAlert" :size="18" />异常接送提醒</h2><span>{{openAlerts.length}} 项尚未解除</span></div><article v-for="row in openAlerts" :key="row.id" class="pickup-alert"><div class="card-top"><div><h3>{{row.studentName}} · {{row.className}}</h3><p>{{row.pickupName}} · 电话后四位 {{row.phoneLast4}} · {{datetime(row.createdAt)}}</p></div><span class="alert-status">{{row.status==='HOLD'?'暂不离校':'等待确认'}}</span></div><p class="alert-reason">{{row.reason}}</p><p class="muted">异常解除前暂停离校。无法联系家长时，请按校区安全流程处理。</p><div v-if="row.canHandle" class="row-actions"><a v-if="row.parentPhone" class="btn primary" :href="`tel:${row.parentPhone}`">联系家长</a><span v-else class="muted">暂无可拨打的监护人电话，请通过校区渠道联系。</span><button class="btn danger" @click="handleAlert(row,'HOLD')">暂不离校</button><button class="btn secondary" @click="handleAlert(row,'RESOLVED')">记录沟通并解除异常</button></div><details class="safety-history"><summary>查看处理记录</summary><p v-for="entry in row.logs" :key="entry.id">{{datetime(entry.createdAt)}} · {{entry.actorName}} · {{entry.note}}</p></details></article></section>
      <div class="pickup-columns"><section class="contacts-section"><div class="section-heading"><h2>常用接送人 <span>{{contacts.data.value?.length||0}}</span></h2><span class="muted">{{child?.name||'请选择孩子'}}</span></div><LoadState :loading="contacts.loading.value" :error="contacts.error.value" :empty="!contacts.data.value?.length" :title="studentId?'还没有常用接送人':'先选择一个孩子'" description="常用联系人供快速选择，实际接送仍须单独授权。" @retry="contacts.refresh"><article v-for="row in contacts.data.value" :key="row.id" class="contact-card"><div class="contact-person"><div class="contact-avatar"><img v-if="row.avatar&&!avatarFailed[row.id]" :src="row.avatar.url" alt="接送人头像" @error="avatarFailed[row.id]=true" /><AppIcon v-else name="UsersRound" :size="24" /></div><div><h3>{{row.name}} <span v-if="row.isDefault" class="default-tag">默认</span></h3><p>{{row.relationship}} · {{row.phoneMasked}}</p><small>常用联系人 · 接送前另行授权</small></div></div><div class="contact-actions"><button v-if="isParent" class="text-btn" @click="authorize(row)">授权接送</button><template v-if="row.canManage"><button class="text-btn" @click="editContact(row)">编辑</button><button v-if="!row.isDefault" class="text-btn" @click="contactDefault(row)">设为默认</button><button class="text-btn danger-text" @click="removeContact(row)">移除</button></template></div></article></LoadState><button v-if="isParent" class="btn secondary full add-contact" :disabled="!studentId" @click="editContact()"><AppIcon name="Plus" :size="16" />添加常用接送人</button></section>
      <section class="authorization-section"><div class="section-heading"><h2>接送授权</h2><button v-if="isParent" class="text-btn" @click="authorize()">申请临时授权</button></div><div class="authorization-tabs" role="tablist" aria-label="接送授权记录"><button role="tab" :aria-selected="authorizationTab==='active'" :class="{active:authorizationTab==='active'}" @click="authorizationTab='active'">当前有效 <span>{{activePickups.length}}</span></button><button role="tab" :aria-selected="authorizationTab==='history'" :class="{active:authorizationTab==='history'}" @click="authorizationTab='history'">历史授权 <span>{{historicalPickups.length}}</span></button></div><LoadState :loading="loading" :error="error" :empty="!shownPickups.length" :title="authorizationTab==='active'?'暂无有效接送授权':'暂无历史授权'" description="授权按学生展示全部记录；老师须在有效时段完成现场核验。" @retry="refresh"><article v-for="row in shownPickups" :key="row.id" class="authorization-card"><div class="card-top"><div class="authorization-person"><span class="contact-avatar small"><AppIcon name="UsersRound" :size="20" /></span><div><h3>{{row.pickupName}} <span class="relationship-tag">{{row.relationship}}</span></h3><p>{{row.studentName}} · {{row.phoneMasked}}</p></div></div><span v-if="row.effectiveStatus==='INVALIDATED'" class="badge gray">已失效</span><StatusBadge v-else :value="row.effectiveStatus" /></div><dl class="authorization-meta"><div><dt>接送时间</dt><dd>{{pickupPeriod(row)}}</dd></div><div><dt>授权类型</dt><dd>{{row.mode==='MULTI'?'多次接送 · 每日最多一次':'单次接送'}}<span v-if="row.usedToday" class="used-tag">今日已接送</span></dd></div><div v-if="row.note"><dt>备注说明</dt><dd>{{row.note}}</dd></div><div><dt>登记监护人</dt><dd>{{row.guardianName}} · {{row.campusName}}</dd></div></dl><p v-if="hasAlert(row.studentId)" class="hold-note"><AppIcon name="TriangleAlert" :size="15" />该孩子有未解除异常，暂缓离校。</p><div class="row-actions"><button v-if="row.canVerify" class="btn secondary" @click="verify(row)">接送码与现场核验</button><button v-if="row.canCheckout" class="btn primary" :disabled="hasAlert(row.studentId)" @click="checkout(row)">已实际交接，确认离校</button><button v-if="row.canRevoke" class="text-btn" @click="revoke(row,true)">重置接送码</button><button v-if="row.canRevoke" class="text-btn danger-text" @click="revoke(row)">撤销授权</button></div><details class="safety-history"><summary>查看授权详情与交接记录</summary><p>交接时核对接送人姓名、电话后四位与接送码。</p><p v-if="row.usageDates?.length">已使用日期：{{row.usageDates.join('、')}}</p><p v-for="entry in row.logs" :key="entry.id">{{datetime(entry.createdAt)}} · {{entry.actorName}} · {{entry.detail}}</p></details></article></LoadState></section></div>
      <details v-if="alerts.data.value?.some(row=>row.status==='RESOLVED')" class="resolved-alerts"><summary>查看已解除的异常记录</summary><article v-for="row in alerts.data.value.filter(row=>row.status==='RESOLVED')" :key="row.id"><h3>{{row.studentName}} · {{row.pickupName}}</h3><p>{{row.reason}} · {{datetime(row.updatedAt)}}</p><p v-for="entry in row.logs" :key="entry.id">{{entry.actorName}} · {{entry.note}}</p></article></details>
    </div>
    <LoadState v-else :loading="loading" :error="error" :empty="!data?.leaves.length" title="当日暂无请假安排" description="整日请假批准后不签到、不扣课，返校前须撤销已批准请假。" @retry="refresh"><div class="summary-grid"><article class="summary-card" v-for="row in data?.leaves" :key="row.id"><div class="card-top"><h2>{{row.studentName}} · {{row.leaveDate}}</h2><StatusBadge :value="row.status" /></div><p class="prose">{{row.reason}}<br>申请人：{{row.createdByName}}<br v-if="row.reviewedByName" />{{row.reviewedByName?'审核人：'+row.reviewedByName+' · '+row.reviewComment:''}}</p><div class="row-actions"><button v-if="row.canReview" class="btn primary" @click="review(row)">审核请假</button><button v-if="row.canCancel" class="btn secondary" @click="cancel(row)">撤销请假</button></div><details class="safety-history"><summary>查看处理记录</summary><p v-for="entry in row.logs" :key="entry.id">{{datetime(entry.createdAt)}} · {{entry.actorName}} · {{entry.detail}}</p></details></article></div></LoadState>
  </section>
  <Teleport to="body"><div v-if="wizardOpen" class="modal-overlay pickup-wizard-overlay" @mousedown.self="closeWizard"><section ref="wizardElement" class="modal pickup-wizard" role="dialog" aria-modal="true" aria-labelledby="pickup-wizard-title" @keydown="wizardKey"><header class="modal-header"><div><span class="eyebrow">{{draftChild?.name}} · 安全接送</span><h2 id="pickup-wizard-title">申请临时接送授权</h2></div><button class="icon-btn" :disabled="busy" aria-label="关闭接送授权" @click="closeWizard"><AppIcon name="X" /></button></header><ol class="authorization-steps" aria-label="授权步骤"><li v-for="(label,index) in ['填写信息','确认授权']" :key="label" :class="{active:step===index+1,complete:step>index+1}" :aria-current="step===index+1?'step':undefined"><span>{{index+1}}</span>{{label}}</li></ol>
      <form @submit.prevent="step===2?submitAuthorization():nextStep()"><div class="modal-body wizard-body"><template v-if="step===1"><h3>接送人信息</h3><label class="field"><span>选择常用联系人</span><SoftSelect v-model="draft.contactId" :options="contactOptions" aria-label="选择接送人" /></label><template v-if="!draft.contactId"><div class="wizard-grid"><label class="field"><span>接送人姓名 *</span><input v-model="draft.pickupName" required maxlength="80" autocomplete="off" placeholder="请输入真实姓名" /></label><label class="field"><span>与孩子关系 *</span><SoftSelect v-model="draft.relationship" required :options="relationships" aria-label="与孩子关系" /></label></div><label class="field"><span>手机号 *</span><input v-model="draft.phone" type="tel" required maxlength="30" inputmode="tel" placeholder="接送人手机号" /></label></template><p v-else class="selected-contact-copy">{{selectedContact?.name}} · {{selectedContact?.relationship}} · {{selectedContact?.phoneMasked}}</p><h3 class="wizard-section-heading">有效时间</h3><div class="mode-switch"><button type="button" :class="{active:draft.mode==='SINGLE'}" @click="draft.mode='SINGLE';draft.endDate=draft.startDate">单次接送</button><button type="button" :class="{active:draft.mode==='MULTI'}" @click="draft.mode='MULTI'">多次接送</button></div><div class="wizard-grid"><label class="field"><span>{{draft.mode==='MULTI'?'开始日期':'接送日期'}} *</span><input v-model="draft.startDate" type="date" required @change="draft.mode==='SINGLE'&&(draft.endDate=draft.startDate)" /></label><label v-if="draft.mode==='MULTI'" class="field"><span>结束日期 *</span><input v-model="draft.endDate" type="date" :min="draft.startDate" required /></label></div><div class="wizard-grid"><label class="field"><span>{{draft.mode==='MULTI'?'每日开始时间':'开始时间'}} *</span><input v-model="draft.startTime" type="time" required /></label><label class="field"><span>{{draft.mode==='MULTI'?'每日截止时间':'截止时间'}} *</span><input v-model="draft.endTime" type="time" required /></label></div><p class="form-hint">{{draft.mode==='MULTI'?'在选定日期范围的每日时段内生效，每日最多接送一次。':'仅在指定日期与时段内生效，使用后失效。'}}</p><label class="field"><span>备注说明</span><textarea v-model="draft.note" rows="3" maxlength="1000" placeholder="例如：亲属来接，已告知孩子" /></label></template>
      <template v-else><h3>请再次确认接送安排</h3><div class="confirmation-person"><span class="contact-avatar"><AppIcon name="UsersRound" :size="25" /></span><div><h3>{{selectedContact?.name||draft.pickupName}} <span class="relationship-tag">{{selectedContact?.relationship||draft.relationship}}</span></h3><p>{{selectedContact?.phoneMasked||draft.phone}}</p></div></div><dl class="authorization-meta confirmation-meta"><div><dt>接送孩子</dt><dd>{{draftChild?.name}}</dd></div><div><dt>授权类型</dt><dd>{{draft.mode==='MULTI'?'多次接送，每日最多一次':'单次接送'}}</dd></div><div><dt>接送日期</dt><dd>{{draft.startDate}}{{draft.mode==='MULTI'?' 至 '+draft.endDate:''}}</dd></div><div><dt>接送时段</dt><dd>{{draft.startTime}}–{{draft.endTime}}</dd></div><div v-if="draft.note"><dt>备注说明</dt><dd>{{draft.note}}</dd></div></dl><div class="authorization-reminder"><strong>请妥善保管本次接送码</strong><p>接送人须主动提供姓名、电话后四位与接送码，并配合现场核对。安排变化时请及时撤销授权。</p></div><label class="confirmation-checkbox"><input v-model="confirmed" type="checkbox" required /><span>我是该孩子当前绑定的监护人，已核对接送人及有效时间，确认本次安排。</span></label></template><div v-if="actionError" class="inline-error" role="alert">{{actionError}}</div></div><footer class="modal-footer"><button type="button" class="btn secondary" :disabled="busy" @click="step===1?closeWizard():(step--,actionError='')">{{step===1?'取消':'上一步'}}</button><button type="submit" class="btn primary" :disabled="busy||(step===2&&!confirmed)">{{busy?'正在处理…':step===2?'确认授权':'下一步'}}</button></footer></form></section></div></Teleport>
</template>

